clc, close, clear all;
%%
%[text] ## Propagation
mu = 398600; %earth, km^3/s^2


r0 = [7000, 0, 0];
v0 = [0, 8.6038, 0];

[r, v, iter] = twoBodyPropagate(r0, v0, 3600, mu);
%[text] $\\mathrm{Energy}\\;\\mathrm{relation}${"editStyle":"visual"}
% semi major axis and period
energy0 = norm(v0)^2/2 - mu/norm(r0); %orbital energy
a = -mu/(2*energy0); %period
T = 2*pi*sqrt(a^3/mu);
dt = T/2 %s %[output:7315af16]
fprintf('Semi-major axis a = %.2f km, period T = %.2f s\n', a, T);   % print a and T %[output:09c1f75e]
%[text] $\\mathrm{Steps}${"editStyle":"visual"}
nSteps = 200; %number of points to sample around the orbit
tVec = linspace(0, T, nSteps); %time vector spanning one period
rAll = zeros(nSteps, 3); %array that stores each position

h0 = cross(r0, v0); %angular momentum vector

for k = 1:nSteps
    [rk, vk] = twoBodyPropagate(r0, v0, tVec(k), mu);
    rAll(k, :) = rk;
end

%%
%[text] ## Plot
figure; %[output:9ab6ba03]
plot3(rAll(:,1), rAll(:,2),rAll(:,3), 'b-', 'LineWidth', 1.5); %trajectory %[output:9ab6ba03]
hold on %[output:9ab6ba03]
plot3(0,0,0, 'go', 'MarkerFaceColor', 'g', 'MarkerSize',8); %central body %[output:9ab6ba03]
plot3(r0(1), r0(2), r0(3), 'r^', 'MarkerFaceColor', 'r'); %starting point %[output:9ab6ba03]
grid on; %[output:9ab6ba03]
axis equal; %[output:9ab6ba03]

xlabel('x (km)'); %[output:9ab6ba03]
ylabel('y (km)'); %[output:9ab6ba03]
zlabel('z (km)'); %[output:9ab6ba03]
title('Two-Body Orbital Propagation'); %[output:9ab6ba03]
legend('Trajectory', 'Central body', 'Initial position', 'Location', 'best'); %[output:9ab6ba03]


fprintf('Converged in %d iterations\n', iter); %[output:54a0f63f]
fprintf('r = [%.4f, %.4f, %.4f] km\n', r); %[output:00df0d1c]
fprintf('v = [%.4f, %.4f, %.4f] km/s\n', v); %[output:51ab61d0]
%[text] 
%[text] $\n\n\\\[\n\\mu = 398600\\ \\mathrm{km^3/s^2},\n\\qquad\n\\Delta t = 3600\\ \\mathrm{s}.\n\\\]\n\nThe initial state is\n\n\\\[\n\\mathbf{r}\_0 = \[7000,\\ -12124,\\ 0\]\\ \\mathrm{km},\n\\qquad\n\\mathbf{v}\_0 = \[2.6679,\\ 4.6210,\\ 0\]\\ \\mathrm{km/s}.\n\\\]\n\nThe state is propagated by\n\n\\\[\n\[\\mathbf{r},\\mathbf{v},\\mathrm{iter}\]\n=\n\\mathrm{twoBodyPropagate}(\\mathbf{r}\_0,\\mathbf{v}\_0,\\Delta t,\\mu).\n\\\]\n\nThe specific orbital energy is\n\n\\\[\n\\varepsilon\_0 = \\frac{\\|\\mathbf{v}\_0\\|^2}{2}\n- \\frac{\\mu}{\\|\\mathbf{r}\_0\\|}.\n\\\]\n\nThe semimajor axis is\n\n\\\[\na = -\\frac{\\mu}{2\\varepsilon\_0},\n\\\]\n\nand the orbital period is\n\n\\\[\nT = 2\\pi\\sqrt{\\frac{a^3}{\\mu}}.\n\\\]\n\nThe orbit is sampled at \\(N=200\\) points over one period using\n\n\\\[\n\\mathbf{t} = \\mathrm{linspace}(0,\\,T,\\,N).\n\\\]\n\nFor each sample time \\(t\_k\\), the state is propagated to obtain the\nposition\n\n\\\[\n\\mathbf{r}\_k = \\mathrm{twoBodyPropagate}(\\mathbf{r}\_0,\\mathbf{v}\_0,t\_k,\\mu),\n\\\]\n\nand the angular momentum vector is\n\n\\\[\n\\mathbf{h}\_0 = \\mathbf{r}\_0 \\times \\mathbf{v}\_0.\n\\\]\n\nThe trajectory is plotted in three dimensions together with the central\nbody at the origin and the initial position \\(\\mathbf{r}\_0\\).\n\nThe final outputs are the semimajor axis \\(a\\), the period \\(T\\), the\npropagated state\n\n\\\[\n\\mathbf{r}, \\qquad \\mathbf{v},\n\\\]\n\nand the number of iterations \\(\\mathrm{iter}\\).$

